mapper.select:
SELECT awls.id, awls.sku_id AS skuId, awls.sku_no AS skuNo, awls.warehouse_id AS warehouseId, awls.warehouse_area_code AS warehouseAreaCode, awls.warehouse_location_code AS warehouseLocationCode, awls.sort, awls.disabled, awls.version, awls.is_deleted AS isDeleted, awls.create_user_id AS createUserId, awls.create_user_name AS createUserName, awls.create_time AS createTime, awls.update_user_id AS updateUserId, awls.update_user_name AS updateUserName, awls.update_time AS updateTime FROM aftersales_warehouse_location_suggest awls LEFT JOIN product_detail pd ON pd.id = awls.sku_id AND pd.is_deleted = false LEFT JOIN LATERAL ( SELECT ppu_inner.ean FROM product_purchase ppu_inner WHERE ppu_inner.sku_id = pd.id AND ppu_inner.is_deleted = false ORDER BY ppu_inner.update_time DESC NULLS LAST LIMIT 1 ) ppu ON true WHERE awls.is_deleted = false
AND awls.sku_no LIKE CONCAT('%', #{params.skuNo}, '%')
AND awls.warehouse_id = #{params.warehouseId}
AND pd.name ILIKE CONCAT('%', #{params.productName}::text, '%')
AND ppu.ean = #{params.ean}::text
AND ${params.sqlMap.default}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
,
awls.create_time DESC
